mapper.select:


    p.del_flag = '0'
    and e.del_flag = '0'

        and p.enterprise_id = #{enterpriseId}


        and p.person_name like concat('%', #{personName}, '%')


        and p.id_card like concat('%', #{idCard}, '%')


        and p.worker_type = #{workerType}


        and p.cert_status = #{certStatus}


        and p.insurance_status = #{insuranceStatus}


        and p.employment_status = #{employmentStatus}


        and p.region_code like concat(#{regionCode}, '%')

    ${params.regionDataScope}

order by p.create_time desc, p.person_id desc

where p.del_flag = '0' and e.del_flag = '0'
and p.enterprise_id = #{enterpriseId}
order by p.person_name asc
